import {SUITS,SUIT_NAMES,cardLabel,cardRank,cardSuit,legalCards,tricksWon,wonTrick,trickReason,startJass,playJass,nextTrick,finishJass,buyMeal,MEALS} from './jass.mjs';
import {exchangeInventory,money} from './progression.mjs';
export function createJassPanels({getState,capture,show,changed,close}){
 const $=id=>document.getElementById(id),message=m=>m?'<p class="panel-message" role="status">'+m+'</p>':'';
 const card=(id,playable=false)=>'<span class="playing-card '+([1,2].includes(cardSuit(id))?'red-card':'')+'"><b>'+({11:'B',12:'D',13:'K',14:'A'}[cardRank(id)]||cardRank(id))+'</b><span aria-hidden="true">'+SUITS[cardSuit(id)]+'</span><small>'+SUIT_NAMES[cardSuit(id)]+'</small></span>';
 function intro(m=''){capture();const s=getState();if(s.jass.active){game(m);return;}show('<span class="eyebrow">BERGRESTAURANT · SÄMIS STAMMTISCH</span><h2>Drei Karten. Drei Stiche.</h2>'+message(m)+'<p>Ein vereinfachtes Jassduell aus dem ursprünglichen Alp-Spiel. Sämi spielt jeden Stich aus. Du antwortest mit einer deiner drei Karten. Zwei gewonnene Stiche gewinnen die Runde.</p><p><strong>Farbpflicht:</strong> Hast du die ausgespielte Farbe, musst du sie bedienen. Andernfalls darfst du eine beliebige Karte spielen, auch Trumpf.</p><p><strong>Rangfolge:</strong> In der ausgespielten Farbe gewinnt Ass vor König, Dame, Bube, 10, 9, 8, 7, 6. Trumpf schlägt jede andere Farbe. Bei Trumpf ist die Reihenfolge Bube, 9, Ass, König, Dame, 10, 8, 7, 6.</p><p>Kein Einsatz und keine Energiekosten. Der erste Rundensieg pro Spieltag bringt CHF 15. Weitere Runden verbessern deinen Bestwert. Es gibt kein Zeitlimit. Jede Kartenwahl wird automatisch gespeichert.</p><p>'+s.jass.wins+' Siege / '+s.jass.runs+' Runden · Bestwert '+s.jass.best+' von 3 Stichen'+(s.jass.prizeDay===s.day?' · Tagespreis schon erhalten':'')+'</p><button id="jass-start" class="primary">Karten mischen & beginnen</button>');$('jass-start').onclick=()=>{capture();const r=startJass(s);if(r.ok)changed();game(r.ok?'Sämi spielt aus. Du antwortest.':r.message);};}
 function game(m=''){capture();const s=getState(),c=s.jass.active;if(!c){intro(m);return;}const review=c.phase!=='choose',last=c.played.length-1,lead=c.opponent[review?last:c.played.length],allowed=legalCards(c),won=tricksWon(c),explanation=last>=0?(wonTrick(c.played[last],c.opponent[last],c.trump)?'Dein Stich!':'Sämis Stich.')+' '+cardLabel(c.played[last])+' gegen '+cardLabel(c.opponent[last])+'. '+trickReason(c.played[last],c.opponent[last],c.trump):'';
 show('<span class="eyebrow">VEREINFACHTES JASSDUELL · TAG '+s.day+'</span><h2>Am Stammtisch mit Sämi</h2>'+message(m)+'<div class="jass-score"><strong>Trumpf '+SUITS[c.trump]+' · '+SUIT_NAMES[c.trump]+'</strong><span>'+won+' gewonnene Stiche · '+c.played.length+' / 3 gespielt</span></div><p data-game-tone="'+(review?(wonTrick(c.played[last],c.opponent[last],c.trump)?'success':'danger'):'neutral')+'">'+(review?(wonTrick(c.played[last],c.opponent[last],c.trump)?'✓ ':'✕ '):'')+(review?explanation:'Sämi legt aus. Wähle eine erlaubte Karte. Farbpflicht: '+SUIT_NAMES[cardSuit(lead)]+'.')+'</p><div class="jass-table"><div><small>Sämi</small>'+card(lead)+'</div>'+(review?'<div><small>Du</small>'+card(c.played[last])+'</div>':'<div class="jass-back" aria-label="Deine Antwort wartet">?</div>')+'</div>'+(c.phase==='choose'?'<div class="jass-hand" aria-label="Deine Handkarten">'+c.hand.map(id=>'<button data-jasscard="'+id+'" aria-label="'+cardLabel(id)+(allowed.includes(id)?' spielen':' · wegen Farbpflicht gesperrt')+'" '+(!allowed.includes(id)?'disabled':'')+'>'+card(id)+'</button>').join('')+'</div><p>Ausgegraute Karten sind wegen der Farbpflicht gesperrt. Mit Trumpf kannst du nur stechen, wenn du die ausgespielte Farbe nicht hast.</p>':c.phase==='review'?'<button id="jass-next" class="primary">'+(c.played.length===3?'Runde auswerten':'Zum nächsten Stich')+'</button>':'<button id="jass-finish" class="primary">Ergebnis & Tagespreis sichern</button>')+'<div class="actions"><button id="jass-pause">Pause & Sicherung</button><button id="jass-rules">Regeln ansehen</button></div><details><summary>Bisherige Stiche</summary>'+c.played.map((id,i)=>'<p>'+(i+1)+'. '+cardLabel(id)+' gegen '+cardLabel(c.opponent[i])+' · '+(wonTrick(id,c.opponent[i],c.trump)?'Du':'Sämi')+'</p>').join('')+'</details>');
 for(const el of document.querySelectorAll('[data-jasscard]'))el.onclick=()=>{capture();const r=playJass(s,Number(el.dataset.jasscard));if(r.ok)changed();game(r.ok?'Karte gespielt und gespeichert.':r.message);};if(c.phase==='review')$('jass-next').onclick=()=>{const r=nextTrick(s);if(r.ok)changed();game(r.ok?'':r.message);};if(c.phase==='done')$('jass-finish').onclick=settle;$('jass-pause').onclick=pause;$('jass-rules').onclick=rules;
 }
 function settle(){const s=getState();if(s.jass.active?.phase!=='done')return;const r=finishJass(s,exchangeInventory);if(!r.ok){game(r.message);return;}changed();show('<span class="eyebrow">JASSRUNDE ABGESCHLOSSEN</span><h2 data-game-tone="'+(r.win?'success':'danger')+'">'+(r.win?'✓ ':'✕ ')+(r.win?'Sämi: «Guet gspielt!»':'Sämi gewinnt diese Runde.')+'</h2><p>'+r.won+' von 3 Stichen gewonnen · Bestwert '+s.jass.best+' von 3.</p><p>'+(r.reward?'Dein Tagespreis: +'+money(r.reward):r.win?'Den Tagespreis hast du heute bereits erhalten.':'Zwei gewonnene Stiche reichen beim nächsten Mal. Kein Einsatz verloren.')+'</p><div class="actions"><button id="jass-again" class="primary">Revanche</button><button id="jass-leave">Vom Tisch aufstehen</button></div>');$('jass-again').onclick=()=>intro();$('jass-leave').onclick=close;}
 function pause(){show('<span class="eyebrow">PAUSE AM STAMMTISCH</span><h2>Die Karten warten</h2><p>Du hast kein Zeitlimit. Jede Wahl bleibt gespeichert; nach dem Neuladen spielst du dieselbe Hand weiter. Erst nach Abschluss oder Abbruch stehst du vom Tisch auf.</p><div class="actions"><button id="jass-resume" class="primary">Weiterspielen</button><button id="jass-abort">Runde abbrechen</button></div>');$('jass-resume').onclick=()=>game();$('jass-abort').onclick=()=>{getState().jass.active=null;changed();close();};changed();}
 function rules(){show('<h2>Trumpf und Farbpflicht</h2><p>Sämi spielt alle drei Stiche aus. Bediene seine Farbe, wenn du sie auf der Hand hast. Sonst ist jede Karte erlaubt. Trumpf sticht eine andere Farbe.</p><p>Normale Farbe: A, K, D, B, 10, 9, 8, 7, 6. Trumpf: B, 9, A, K, D, 10, 8, 7, 6. Zwei Stiche gewinnen die Runde. Dieses kurze Duell ist kein vollständiger Schieber-Jass.</p><button id="jass-back" class="primary">Zur Hand zurück</button>');$('jass-back').onclick=()=>game();}
 function menu(m=''){capture();const s=getState();show('<span class="eyebrow">BERGRESTAURANT ZUM GIPFEL</span><h2>Eine warme Mahlzeit</h2>'+message(m)+'<p>'+money(s.coins)+' · Energie '+Math.round(s.energy)+' / 100 · Ausdauer '+Math.round(s.stamina)+' / 100. Beide Gerichte füllen Energie und Ausdauer sofort vollständig auf.</p><div class="item-grid">'+Object.entries(MEALS).map(([id,a])=>'<article class="item-card"><h3>'+a.name+'</h3><p>'+money(a.price)+'</p><button data-meal="'+id+'" '+(s.coins<a.price||(s.energy>=100&&s.stamina>=100)?'disabled':'')+'>Bestellen</button></article>').join('')+'</div><p>Am Stammtisch wartet Sämi auf eine kurze Jassrunde. Der Ausgang führt direkt zurück ins Bergdorf.</p>');for(const el of document.querySelectorAll('[data-meal]'))el.onclick=()=>{capture();const r=buyMeal(s,el.dataset.meal,exchangeInventory);if(r.ok)changed();menu(r.message);};}
 return{intro,game,menu};
}
